css:
/* The footer sits on the darker chrome, and its first column is wider than the
   three link columns, which the twelve-column grid cannot express on its own. */
/* The legal strip below carries the footer's closing padding, so this band
   runs straight into its divider the way the handoff's does. */
[data-bz-section="site-footer"] > .bz-section { background: var(--chrome); padding-block: 80px 60px }
[data-bz-section="site-footer"] [data-bz-node="sf-row"] { grid-template-columns: 1.4fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 0 }
[data-bz-section="site-footer"] [data-bz-node="sf-row"] > .bz-col { grid-column: auto }
[data-bz-section="site-footer"] .bz-block { padding-block: 0 }
[data-bz-section="site-footer"] .bz-block + .bz-block { padding-block-start: 0 }
[data-bz-section="site-footer"] h2 { font: 700 11px/1 var(--font-body); letter-spacing: .1em; text-transform: uppercase; color: var(--chrome-label); margin: 0 0 16px }
[data-bz-section="site-footer"] .bz-menu .bz-nav { gap: 10px }
[data-bz-section="site-footer"] .bz-navitem { font-size: 14px; line-height: 1.6 }
[data-bz-section="site-footer"] .bz-navitem > a { color: #fff; font-size: 14px; line-height: 1.6; font-weight: 400; font-family: var(--font-body); padding: 0 }
[data-bz-section="site-footer"] .bz-navitem > a:hover { text-decoration: underline }
/* Doubled attribute: this component's own `.bz-block + .bz-block` rule sits at
   (0,3,0) and was zeroing the three paddings that set the first column. */
[data-bz-section="site-footer"] [data-bz-node="sf-blurb"][data-bz-node] { padding-block-start: 16px }
[data-bz-section="site-footer"] p { color: var(--chrome-meta); font-size: 13px; line-height: 1.6; max-width: 260px; margin: 0 }
[data-bz-section="site-footer"] .bz-logo__img { height: 56px; width: auto; display: block }
/* The brand anchor is inline, so its line box added 10px under the mark. */
[data-bz-section="site-footer"] [data-bz-node="sf-logo"] .bz-brand { display: block }
[data-bz-section="site-footer"] [data-bz-node="sf-logo"] { padding-block: 0 }
[data-bz-section="site-footer"] .bz-btn--link { color: var(--chrome-meta); padding: 0; min-height: 0; text-decoration: none }
[data-bz-section="site-footer"] .bz-btn--link:hover { color: #fff; text-decoration: underline }
[data-bz-section="site-footer"] [data-bz-node="sf-email"][data-bz-node] { padding-block-start: 12px }
[data-bz-section="site-footer"] [data-bz-node="sf-email"] .bz-btns { margin-block: 0 }
[data-bz-section="site-footer"] [data-bz-node="sf-social"][data-bz-node] { padding-block-start: 19px }
[data-bz-section="site-footer"] [data-bz-node="sf-social"] .ss-social { gap: 14px }
[data-bz-section="site-footer"] [data-bz-node="sf-social"] .ss-social__a img { width: 16px; height: 16px }
@media (max-width: 1100px) { [data-bz-section="site-footer"] [data-bz-node="sf-row"] { grid-template-columns: 1fr 1fr } }
@media (max-width: 640px) { [data-bz-section="site-footer"] [data-bz-node="sf-row"] { grid-template-columns: 1fr } }
